answer_vi:
Pinia plugins cho phép extend tất cả stores — thêm properties, wrap actions, subscribe to changes:

```typescript
import { PiniaPluginContext } from 'pinia'

// Plugin thêm $reset cho tất cả stores (setup stores không có built-in reset)
function resetPlugin({ store, options }: PiniaPluginContext) {
  // Lưu initial state
  const initialState = JSON.parse(JSON.stringify(store.$state))

  store.$reset = () => {
    // Phải clone: $patch gán array/Map theo tham chiếu → sau reset store dùng chung
    // mảng với initialState, reset lần 2 sẽ trả về state đã bị sửa
    store.$patch(structuredClone(initialState))
  }
}

// Plugin logging actions
function logPlugin({ store }: PiniaPluginContext) {
  store.$onAction(({ name, args, after, onError }) => {
    console.log(`[Store: ${store.$id}] Action: ${name}`, args)
    after((result) => console.log('Result:', result))
    onError((error) => console.error('Error:', error))
  })
}

// Register plugins
const pinia = createPinia()
pinia.use(resetPlugin)
pinia.use(logPlugin)

// Sử dụng
const store = useCounterStore()
store.$reset()  // Available từ plugin
```

Use cases: logging, error tracking (Sentry), optimistic updates, undo/redo, sync với localStorage, add `$api` property

answer_en:
Pinia plugins extend all stores — add properties, wrap actions, subscribe to changes:

```typescript
function resetPlugin({ store }: PiniaPluginContext) {
  const initial = JSON.parse(JSON.stringify(store.$state))
  // clone it: $patch assigns arrays/Maps by reference, so a second reset would restore mutated state
  store.$reset = () => store.$patch(structuredClone(initial))
}

function logPlugin({ store }: PiniaPluginContext) {
  store.$onAction(({ name, args, after, onError }) => {
    console.log(`[${store.$id}] ${name}`, args)
    after((r) => console.log('Result:', r))
    onError((e) => console.error('Error:', e))
  })
}

const pinia = createPinia()
pinia.use(resetPlugin)
pinia.use(logPlugin)

// Usage
const store = useCounterStore()
store.$reset()  // Added by plugin
```

Use cases: logging, Sentry error tracking, undo/redo, localStorage sync.
